// main.js — browser bootstrap: loads GLB data, drives the engine, presents frames,
// exposes window.__raptor for the automated grader contract.
import { loadGLB } from './glb.js';
import { Raptor } from './engine.js';
import { SoundEngine } from './audio.js';

const canvas = document.getElementById('raptor-canvas');
canvas.width = 320;
canvas.height = 200;
const ctx = canvas.getContext('2d');
const imageData = ctx.createImageData(320, 200);
const imgPix = imageData.data;

const keys = { up: false, down: false, left: false, right: false, fire: false };

function onKeyDown(e) {
  switch (e.key) {
    case 'ArrowUp': keys.up = true; e.preventDefault(); break;
    case 'ArrowDown': keys.down = true; e.preventDefault(); break;
    case 'ArrowLeft': keys.left = true; e.preventDefault(); break;
    case 'ArrowRight': keys.right = true; e.preventDefault(); break;
    case ' ': keys.fire = true; e.preventDefault(); break;
  }
  window.__raptor.audio.contextState = audio.contextState();
  audio.unlock();
}
function onKeyUp(e) {
  switch (e.key) {
    case 'ArrowUp': keys.up = false; break;
    case 'ArrowDown': keys.down = false; break;
    case 'ArrowLeft': keys.left = false; break;
    case 'ArrowRight': keys.right = false; break;
    case ' ': keys.fire = false; break;
  }
}
window.addEventListener('keydown', onKeyDown);
window.addEventListener('keyup', onKeyUp);

// ---- grader contract ----
window.__raptor = {
  ready: false,
  player: { x: 0, y: 0, alive: true },
  projectiles: [],
  enemies: [],
  hud: { score: 0, shields: 0 },
  audio: { contextState: 'suspended', sfxCount: 0 },
  wave: 0,
  sectorComplete: false,
};

const audio = new SoundEngine();

// render current engine buffer to the canvas.
function render(fadeAmount) {
  const buf = game.buf;
  const gpal = game.gpal;
  for (let i = 0; i < buf.length; i++) {
    const c = buf[i] * 3;
    let r = gpal[c] * fadeAmount;
    let g = gpal[c + 1] * fadeAmount;
    let b = gpal[c + 2] * fadeAmount;
    const o = i * 4;
    imgPix[o] = r <= 63 ? (r << 2) | 0 : 255;
    imgPix[o + 1] = g <= 63 ? (g << 2) | 0 : 255;
    imgPix[o + 2] = b <= 63 ? (b << 2) | 0 : 255;
    imgPix[o + 3] = 255;
  }
  ctx.putImageData(imageData, 0, 0);
}

function renderTextScreen(text, sub) {
  // draw on a plain dark background with the game font
  const buf = game.buf;
  buf.fill(0);
  const font = game.glb1.raw('GAME_FNT');
  const { print } = { print: null };
  // direct: use engine print through a helper
  game.printAt(buf, font, 160, 92, text, 34, true);
  if (sub) game.printAt(buf, font, 160, 120, sub, 15, true);
}

function syncRaptor() {
  const R = window.__raptor;
  R.player.x = game.playerx;
  R.player.y = game.playery;
  R.player.alive = game.energy > 0 && !game.dead;
  R.projectiles = game.shots.map((s) => ({ x: s.x, y: s.y, owner: 'player' }));
  for (const s of game.eshots) R.projectiles.push({ x: s.x, y: s.y, owner: 'enemy' });
  R.enemies = game.enemies.map((e, i) => ({
    id: i, hp: e.hits, x: e.x, y: e.y, alive: true,
  }));
  R.hud.score = Math.floor(game.score);
  R.hud.shields = game.energy;
  R.audio.contextState = audio.contextState();
  R.audio.sfxCount = audio.sfxCount;
  R.wave = game.wave + 1; // 1-based wave number
  R.sectorComplete = game.sectorComplete;
}

let game;
let phase = 'loading';      // loading -> playing -> between -> complete -> death
let betweenTimer = 0;
let nextWave = 0;
let deathTimer = 0;
const LOGIC_HZ = 70 / 3;

async function boot() {
  const [glb0, glb1] = await Promise.all([
    loadGLB('data/FILE0000.GLB'),
    loadGLB('data/FILE0001.GLB'),
  ]);

  game = new Raptor(glb0, glb1);
  game.setAudio({
    play: (name, vol) => audio.play(name, vol),
  });
  game.init();

  // register every digital sfx from FILE0000.GLB
  for (const it of glb0.items) {
    if (it.name && it.name.endsWith('_FX')) {
      audio.register(it.name, glb0.raw(it.name));
    }
  }

  game.startWave(0);
  phase = 'playing';
  syncRaptor();

  let last = performance.now();
  let acc = 0;

  function step() {
    if (phase === 'playing') {
      game.keys = keys;
      game.frame();
      if (game.fadeIn > 0) game.fadeIn--;
      if (game.fadeIn <= 0) window.__raptor.ready = true;
      if (game.dead) {
        phase = 'death';
        deathTimer = 0;
      } else if (game.end_wave) {
        if (game.wave >= 8) {
          phase = 'complete';
          game.sectorComplete = true;
        } else {
          phase = 'between';
          betweenTimer = 60;
          nextWave = game.wave + 1;
        }
      }
    } else if (phase === 'between') {
      if (--betweenTimer <= 0) {
        game.startWave(nextWave);
        phase = 'playing';
      }
    } else if (phase === 'death') {
      if (++deathTimer > 120) {
        game.startWave(0);
        game.score = 0;
        phase = 'playing';
      }
    }
    syncRaptor();
  }

  function loop(now) {
    requestAnimationFrame(loop);
    if (game) {
      acc += now - last;
      last = now;
      let guard = 0;
      while (acc >= 1000 / LOGIC_HZ && guard++ < 4) {
        step();
        acc -= 1000 / LOGIC_HZ;
      }
      if (acc > 1000 / LOGIC_HZ) acc = 0;
      const fadeAmount = game.fadeIn > 0 ? (1 - game.fadeIn / 64) : 1;
      if (phase === 'complete') {
        // sector-complete screen
        game.buf.fill(0);
        game.printAt(game.buf, game.glb1.raw('GAME_FNT'), 160, 84, 'SECTOR 1', 34, true);
        game.printAt(game.buf, game.glb1.raw('GAME_FNT'), 160, 104, 'COMPLETE', 34, true);
        render(1);
        renderCompleteText();
      } else {
        render(Math.max(0, Math.min(1, fadeAmount)));
        if (phase === 'death' && (deathTimer >> 1) & 1) {
          // blink "GAME OVER"
          game.printAt(game.buf, game.glb1.raw('GAME_FNT'), 160, 90, 'GAME OVER', 34, true);
          render(1);
        }
      }
    }
  }
  requestAnimationFrame(loop);
}

function renderCompleteText() {
  // already drawn via printAt in the loop path; helper kept for structure
}

// keep window listeners even before boot finishes
window.__raptor.audio.contextState = 'suspended';

boot().catch((e) => {
  console.error(e);
  const el = document.getElementById('status');
  if (el) el.textContent = 'Failed to load game data: ' + e.message;
});

