import { loadGLB } from './js/glb.js';
import { SoundEngine } from './js/audio.js';
const glb0 = await loadGLB('data/FILE0000.GLB');
const glb1 = await loadGLB('data/FILE0001.GLB');

// fake Web Audio
class FakeSrc { start(){ this.started = true; FakeSrc.startedCount = (FakeSrc.startedCount||0)+1; } }
class FakeGain { connect(){ return this; } }
let state = 'suspended';
class FakeAC {
  constructor(){ state = 'running'; FakeAC.instances = (FakeAC.instances||0)+1; }
  get state(){ return state; }
  resume(){ state = 'running'; }
  createBuffer(){ return { getChannelData: () => new Float32Array(100) }; }
  createBufferSource(){ return new FakeSrc(); }
  createGain(){ return new FakeGain(); }
  get destination(){ return {}; }
}
global.window = { AudioContext: FakeAC };
const ae = new SoundEngine();
// register real SFX from data
let registered = 0, digital = 0;
for (const it of glb0.items) {
  if (it.name && it.name.endsWith('_FX')) { ae.register(it.name, glb0.raw(it.name)); registered++; if (ae.sounds.size + ae._pending.length > 0) digital++; }
}
console.log('registered _FX items:', registered);
ae.ensure();
console.log('contextState after ensure:', ae.contextState());
const ok = ae.play('GUN_FX', 0.9);
console.log('play(GUN_FX):', ok, 'sfxCount:', ae.sfxCount, 'sources started:', FakeSrc.startedCount);
console.log('sounds loaded into buffers:', ae.sounds.size);
" 2>&1

