  const rate = raw.length>=8 ? vv.getUint16(2, true) : 0;
  const n = raw.length>=8 ? vv.getUint32(4, true) : 0;
  console.log(k, 'placeholder@', v, 'audio@', audioIdx, 'len', raw.length, 'b0', raw[0], 'rate', rate, 'samples', n);
}
