// M4 smoke: audio + HUD contract through the real js/main.js path in Node.
let fakeNow = 0;
global.performance = { now: () => fakeNow };
function makeCanvas() {
  const imageData = { data: new Uint8ClampedArray(320 * 200 * 4), width: 320, height: 200 };
  return { width: 0, height: 0, style: {}, getContext: () => ({ createImageData: () => imageData, putImageData: () => {} }) };
}
// fake Web Audio
let acState = 'suspended';
let sourcesStarted = 0;
class FakeGain { constructor(){ this.gain = { value: 0 }; } connect(){ return {}; } }
class FakeAC {
  constructor(){ acState = 'running'; this.buffers = []; }
  get state(){ return acState; }
  resume(){ acState = 'running'; }
  createBuffer(n, len, rate){ return { n, len, rate, getChannelData: () => new Float32Array(len) }; }
  createBufferSource(){ sourcesStarted++; return { buffer: null, connect(){ return {}; }, start(){} }; }
  createGain(){ return new FakeGain(); }
  get destination(){ return {}; }
}
const canvas = makeCanvas();
global.document = { getElementById: (id) => (id === 'raptor-canvas' ? canvas : { textContent: '', set textContent(v) { this._t = v; } }) };
const handlers = {};
global.addEventListener = (type, fn) => { handlers[type] = fn; };
global.window = { AudioContext: FakeAC };
global.window.addEventListener = (t, f) => { handlers[t] = f; };
global.requestAnimationFrame = (cb) => { setTimeout(() => { fakeNow += 16.67; cb(fakeNow); }, 0); };
const fireEvent = (type, key) => { handlers[type] && handlers[type]({ key, preventDefault: () => {} }); };

await import('../js/main.js');
await new Promise((r) => setTimeout(r, 60));
const R = global.__raptor;
await new Promise((r) => setTimeout(r, 600));
console.log('audio before gesture:', JSON.stringify(R.audio), 'hud:', JSON.stringify(R.hud));
fireEvent('keydown', 'ArrowUp');   // user gesture -> AudioContext unlock
await new Promise((r) => setTimeout(r, 100));
console.log('audio after gesture:', JSON.stringify(R.audio));
const sfxBefore = R.audio.sfxCount;
fireEvent('keydown', ' ');         // hold fire -> GUN_FX
await new Promise((r) => setTimeout(r, 400));
fireEvent('keyup', ' ');
